MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  assert(image_info != (ImageInfo *) NULL);
  assert(images != (Image *) NULL);
  assert(filename != (const char *) NULL);
  assert(exception != (ExceptionInfo *) NULL);
  (void) memset(exception, 0, sizeof(*exception));

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return (MagickFalse);

  if (images->next != (Image *) NULL)
  {
    Image
      *next;

    for (image = images; image != (Image *) NULL; image = next)
    {
      char
        *temp_filename;

      next = image->next;
      temp_filename = CloneString(filename);
      if (temp_filename == (char *) NULL)
      {
        DestroyImageInfo(clone_info);
        return (MagickFalse);
      }

      SetImageInfo(clone_info, image);
      if (clone_info->adjoin != MagickFalse)
      {
        status = WriteImage(clone_info, image, &exception);
        temp_filename = (char *) RelinquishMemory(temp_filename);
        continue;
      }

      status = WriteImage(clone_info, image, &exception);
      temp_filename = (char *) RelinquishMemory(temp_filename);
      if (status == MagickFalse)
      {
        DestroyImageInfo(clone_info);
        return (MagickFalse);
      }
    }
  }
  else
  {
    status = WriteImage(clone_info, images, exception);
    if (status == MagickFalse)
    {
      DestroyImageInfo(clone_info);
      return (MagickFalse);
    }
  }

  DestroyImageInfo(clone_info);
  return (MagickTrue);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  ssize_t
    i;

  assert(image_info != (const ImageInfo *) NULL);
  assert(images != (Image *) NULL);
  assert(filename != (const char *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return (MagickFalse);

  for (i = 0, image = images; image != (Image *) NULL; image = image->next)
  {
    char
      *output_filename;

    output_filename = FormatMagickPath(clone_info->filename, i, filename);
    if (output_filename == (char *) NULL)
    {
      DestroyImageInfo(clone_info);
      return (MagickFalse);
    }

    clone_info->adjoin = MagickFalse;
    status = WriteImage(clone_info, image, output_filename, exception);
    if (status == MagickFalse)
    {
      DestroyImageInfo(clone_info);
      MagickFreeMemory(output_filename);
      return (MagickFalse);
    }

    MagickFreeMemory(output_filename);
    i++;
  }

  DestroyImageInfo(clone_info);
  return (MagickTrue);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images, const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  MagickBooleanType
    status;

  ImageInfo
    *clone_info;

  assert(image_info != (ImageInfo *) NULL);
  assert(images != (Image *) NULL);
  assert(filename != (const char *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return(MagickFalse);

  status = MagickTrue;
  image = images;
  do
  {
    char
      *temp_filename;

    temp_filename = CopyMagickString((char *) NULL, filename, MaxTextLength);
    if (image->scene != 0)
    {
      char
        scene[MagickPathExtent];

      FormatString(scene, "%u", image->scene);
      temp_filename = ReplaceString(temp_filename, "%d", scene);
    }
    clone_info->filename = temp_filename;
    SetImageInfo(clone_info);
    if (image->scene == 0)
      image->scene = 1;
    else
      image->scene++;
    if (image->next == (Image *) NULL)
      clone_info->adjoin = MagickFalse;
    else
      clone_info->adjoin = MagickTrue;
    status = WriteImage(clone_info, image, exception);
    if (status == MagickFalse)
      break;
    image = GetNextImageInList(image);
  }
  while (image != (Image *) NULL);

  clone_info = DestroyImageInfo(clone_info);
  return(status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  ImageInfo
    *write_info;

  MagickBooleanType
    status;

  register ssize_t
    i;

  write_info = CloneImageInfo(image_info);
  if (write_info == (ImageInfo *) NULL)
    return (MagickFalse);

  status = MagickTrue;
  for (i = 0; i < (ssize_t) GetImageListLength(images); i++)
  {
    image = GetNthImageInList(images, i);
    if (image == (Image *) NULL)
    {
      status = MagickFalse;
      continue;
    }

    image->scene = i + 1;
    if (i == 0)
    {
      if (write_info->adjoin != MagickFalse)
      {
        (void) CopyMagickString(write_info->filename, filename, MAGICK_PATH_MAX);
        (void) FormatMagickString(write_info->filename, MAGICK_PATH_MAX, "%s", filename);
      }
    }
    else
    {
      (void) FormatMagickString(write_info->filename, MAGICK_PATH_MAX,
                                "%s-%05lu", filename, (unsigned long) image->scene);
    }

    status &= WriteImage(write_info, image, exception);
  }

  write_info = DestroyImageInfo(write_info);
  return (status != MagickFalse ? MagickTrue : MagickFalse);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images, const char *filename, ExceptionInfo *exception) {
  Image
    *image;

  ImageInfo
    *write_info;

  MagickBooleanType
    status;

  register ssize_t
    i;

  write_info = CloneImageInfo(image_info);
  if (write_info == (ImageInfo *) NULL)
    return(MagickFalse);

  status = MagickTrue;
  for (i = 0; i < (ssize_t) GetImageListLength(images); i++) {
    image = GetImageList(images, i);
    if (image == (Image *) NULL)
      continue;

    if (image->scene != (ssize_t) i)
      image->scene = i;

    SetImageInfo(write_info, image);
    if (write_info->adjoin != MagickFalse) {
      if (i == 0) {
        status = WriteImage(write_info, image, exception);
        if (status == MagickFalse)
          break;
      }
    }
    else {
      char
        *output_filename;

      output_filename = FormatImageFilename(write_info, image, filename);
      if (output_filename == (char *) NULL)
        continue;
      status = WriteImage(write_info, image, exception);
      output_filename = (char *) RelinquishMemory(output_filename);
      if (status == MagickFalse)
        break;
    }
  }

  write_info = DestroyImageInfo(write_info);
  return(status);
}
